    } catch (ModelDuplicateException mde) {
        logger.error("Conflict detected", mde);
        throw ErrorResponse.exists(mde.getMessage());
    } catch (ModelException e) {
        throw ErrorResponse.error(e.getMessage(), Response.Status.BAD_REQUEST);
    }
}

